import{_ as t,o as e,c as r,a2 as s}from"./chunks/framework.B2QVIpOM.js";const h=JSON.parse('{"title":"张祝珊英文中学 · 2020-21年度 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-54053d7d","school_zh":"张祝珊英文中学","school_en":"—","grade":"s1","year":"2020-21","year_label":"2020-21年度","type":"interview","title":"张祝珊英文中学 · 2020-21年度 · 中一 · 面试","anonymous":true,"source_ids":["C1821-CCSC-2021-SPORT"],"rounds":["unknown"]},"headers":[],"relativePath":"reports/school-54053d7d/s1/2020-21-interview.md","filePath":"reports/school-54053d7d/s1/2020-21-interview.md"}'),a={name:"reports/school-54053d7d/s1/2020-21-interview.md"};function n(p,o,c,l,d,i){return e(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="张祝珊英文中学-·-2020-21年度-·-中一-·-面试" tabindex="-1">张祝珊英文中学 · 2020-21年度 · 中一 · 面试 <a class="header-anchor" href="#张祝珊英文中学-·-2020-21年度-·-中一-·-面试" aria-label="Permalink to &quot;张祝珊英文中学 · 2020-21年度 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-54053d7d">← 返回张祝珊英文中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c1821-ccsc-2021-sport" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-c1821-ccsc-2021-sport" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-c1821-ccsc-2021-sport}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一体育专长甄选</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>乒乓球专项评估</strong></p><p>属于含乒乓球测试的特别队甄选反馈。一组先约10至15分钟填写英文问卷，书写英语、沟通可用中文；约30分钟打两场比赛，同组3男2女；学生英语面谈约20至25分钟，家长粤语面谈约10至15分钟。</p><p><strong>后续申请</strong></p><p>家长当时获告知12月底前电话通知，获特别队取录后仍需在校务人员面前填写自行申请表并参加自行面试；此为该年度家长反馈。</p></blockquote><blockquote><p><strong>资料填写：</strong> 英语</p><p><strong>基本资料、训练与学业安排</strong></p><p>填写中英文名、学校、班别、运动及所属球会、成就；问闲暇活动、接触过哪些运动、是否有私人教练或补习、为什么选择乒乓球，以及如何平衡学习和运动。选择题涉及每周训练天数、是否与家人出游、家人是否喜爱运动、考试周及考试当天是否打球。</p></blockquote><blockquote><p><strong>学生面谈：</strong> 英语</p><p><strong>兴趣、同伴与阅读</strong></p><p>问姓名、是否喜欢乒乓球、闲暇做什么、参加过什么运动及原因；有考生被问两人的不同及如何分辨。另问喜欢哪本书及原因。</p><p><strong>校园与家庭生活</strong></p><p>介绍小学生活，对张祝珊有何认识、是否有亲友在校就读、有没有兄弟姊妹、家中是否有家务助理及负责什么。</p></blockquote><blockquote><p><strong>家长面谈：</strong> 粤语</p><p><strong>转校原因、训练与自理</strong></p><p>问曾经转校的原因、目前每周训练几天。老师强调学术要求和学生自理能力，家长则介绍在家鼓励学习、接触英文节目及英语交流的方式，并举例说明孩子如何自理。</p></blockquote>',12)])])}const _=t(a,[["render",n]]);export{h as __pageData,_ as default};
